/**
 * Platform tests on the SYNTHETIC GeoTIFF fixtures in public/workspaces/sandbox
 * (generated by backend `python -m terrapulse make-test-rasters`).
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { capabilitiesFor } from "./analysis/capabilities";
import { deriveFromDem, demToTerrainGrid } from "./analysis/demProducts";
import { computeSarChange } from "./analysis/sarChange";
import { crsFromEpsg, toLonLat } from "./data/crs";
import { datasetFromFile, inspectDataset } from "./data/inspect";
import { classifyRaster } from "./data/inspect/classifyRaster";
import { profileRecords } from "./data/inspect/table";
import { inspectGeoJson } from "./data/inspect/vector";
import { planChart } from "./visualization/charts/chartPlan";
import type { Dataset } from "./data/types";

const DIR = "public/workspaces/sandbox/";

async function load(name: string, patch: Partial<Dataset> = {}): Promise<Dataset> {
  const buf = readFileSync(DIR + name);
  const ds = { ...datasetFromFile(new File([buf], name)), ...patch };
  return { ...ds, ...(await inspectDataset(ds)) } as Dataset;
}

describe("raster inspection", () => {
  it("recognises a DEM and its UTM CRS", async () => {
    const dem = await load("synthetic_dem_utm45.tif");
    expect(dem.kind).toBe("dem");
    expect(dem.raster?.crs.epsg).toBe(32645);
    expect(dem.raster?.nodata).toBe(-9999);
    expect(dem.raster?.stats.min).toBeGreaterThan(-1000); // nodata excluded
    const [lon, lat] = dem.raster!.lonLatCorners![0];
    expect(lon).toBeGreaterThan(87.5); expect(lon).toBeLessThan(88.5);
    expect(lat).toBeGreaterThan(15); expect(lat).toBeLessThan(16);
  });

  it("recognises SAR in dB from name + values and offers change detection", async () => {
    const a = await load("synthetic_sar_VV_before.tif", { date: "2000-01-01" });
    const b = await load("synthetic_sar_VV_after.tif", { date: "2000-02-01" });
    expect(a.kind).toBe("sar");
    expect(a.raster?.sarScale).toBe("db");
    expect(a.raster?.polarization).toBe("VV");
    const cap = capabilitiesFor(a, [a, b], null).find((c) => c.id === "sar-change")!;
    expect(cap.enabled).toBe(true);
    expect(cap.partners?.[0].id).toBe(b.id);
  });

  it("change detection finds the planted brightening and darkening", async () => {
    const a = await load("synthetic_sar_VV_before.tif", { date: "2000-01-01" });
    const b = await load("synthetic_sar_VV_after.tif", { date: "2000-02-01" });
    const chg = await computeSarChange(b, a); // given in the wrong order on purpose
    expect(chg.kind).toBe("change");
    expect(chg.provenance).toBe("derived");
    expect(chg.notes.some((n) => n.includes("swapped"))).toBe(true);
    const v = chg.grid!.values;
    const up = v.filter((x) => x > 4).length, down = v.filter((x) => x < -5).length;
    // planted: ~1300 px +6 dB and ~822 px −8 dB at full res (256²); output is full res here
    expect(up).toBeGreaterThan(900);
    expect(down).toBeGreaterThan(600);
  });

  it("builds a terrain grid and slope from a DEM", async () => {
    const dem = await load("synthetic_dem_utm45.tif");
    const g = await demToTerrainGrid(dem, 128);
    expect(g.cols).toBe(128);
    expect(g.sizeMeters[0]).toBeCloseTo(256 * 30, -1);
    expect(g.heights.every(Number.isFinite)).toBe(true);
    const slope = await deriveFromDem(dem, "slope");
    expect(slope.raster?.unit).toBe("°");
    expect(slope.raster!.stats.max).toBeLessThan(90);
  });
});

describe("classification heuristics", () => {
  const s = (p2: number, p98: number, min = p2, max = p98) => ({ min, max, mean: (p2 + p98) / 2, p2, p98, validFraction: 1 });
  it("linear SAR power", () => expect(classifyRaster("S1A_IW_RTC_VH.tif", 1, false, s(0.001, 0.4)).sarScale).toBe("linear"));
  it("coherence", () => expect(classifyRaster("ifg_coh.tif", 1, false, s(0.1, 0.9, 0, 1)).kind).toBe("coherence"));
  it("binary mask", () => expect(classifyRaster("x.tif", 1, true, s(0, 1)).kind).toBe("mask"));
  it("optical", () => expect(classifyRaster("scene.tif", 4, true, s(10, 3000)).kind).toBe("optical"));
  it("unnamed elevation", () => expect(classifyRaster("tile.tif", 1, false, s(2800, 5600)).kind).toBe("dem"));
});

describe("crs", () => {
  it("UTM 45N round numbers", () => {
    const [lon, lat] = toLonLat(crsFromEpsg(32645), 500000, 3080000)!;
    expect(lon).toBeCloseTo(87, 3); expect(lat).toBeGreaterThan(27.8); expect(lat).toBeLessThan(27.9);
  });
  it("unknown projection is flagged", () => expect(crsFromEpsg(2193).supported).toBe(false));
});

describe("vector + table + charts", () => {
  it("GeoJSON geometry is wrapped and described", () => {
    const { vector } = inspectGeoJson({ type: "Point", coordinates: [86.6, 27.8] });
    expect(vector.featureCount).toBe(1);
    expect(vector.bbox).toEqual([86.6, 27.8, 86.6, 27.8]);
  });
  it("non-GeoJSON JSON is rejected", () => expect(() => inspectGeoJson({ hello: 1 })).toThrow());

  it("browser profiler finds coordinates, target and group", () => {
    const recs = Array.from({ length: 40 }, (_, i) => ({ lat: 27 + i / 100, lon: 86, site: `S${i % 4}`, wet: i % 3 ? "no" : "yes", v: i }));
    const sh = profileRecords("t", recs, ["lat", "lon", "site", "wet", "v"]);
    expect(sh.coordinates?.lat).toBe("lat");
    expect(sh.suggestions.target_candidates).toContain("wet");
    expect(sh.suggestions.group_candidates).toContain("site");
  });

  it("time-series sheet gets a line chart with series", () => {
    const recs = [3, 4, 5].flatMap((lake) => ["2000-01-01", "2010-01-01", "2020-01-01"].map((d, k) => ({ Date: d, Lake_Number: lake, Area_km2: 0.05 + k * 0.01, Area_Error_km2: 0.01 })));
    const sh = profileRecords("ts", recs, ["Date", "Lake_Number", "Area_km2", "Area_Error_km2"]);
    sh.suggestions.group_candidates = ["Lake_Number"];
    const plan = planChart(sh);
    expect(plan.type).toBe("line");
    if (plan.type === "line") { expect(plan.ys[0]).toBe("Area_km2"); expect(plan.series).toBe("Lake_Number"); }
  });
});

describe("leakage detectors", () => {
  it("flags outcome-derived and single-column separators, not ordinary features", async () => {
    const { suspectedLabelDerived, singleColumnSeparators } = await import("./data/inspect/table");
    const recs = Array.from({ length: 200 }, (_, i) => {
      const y = i % 5 === 0 ? 1 : 0;
      return { y, area: y ? 100 + i : 0, cls: y ? (i % 2 ? "slide" : "flow") : "none", slope: (i * 37) % 60 };
    });
    const sh = profileRecords("t", recs, ["y", "area", "cls", "slope"]);
    expect(suspectedLabelDerived(sh, "y").sort()).toEqual(["area", "cls"]);
    expect(singleColumnSeparators(sh, "y")).toContain("cls");
    expect(singleColumnSeparators(sh, "y")).not.toContain("slope");
  });
});
